#include <assert.h>
#include <stdio.h>
#include "../source/core/editor.h"
int main(void){VEState e={0};char text[256]="alpha beta alpha";int cursor=5;e.anchor=0;e.end=5;assert(ve_insert(&e,text,&cursor,sizeof(text),"A",1000000,true));assert(!strcmp(text,"A beta alpha"));assert(ve_history(&e,text,&cursor,false)&&!strcmp(text,"alpha beta alpha"));assert(ve_history(&e,text,&cursor,true)&&!strcmp(text,"A beta alpha"));strcpy(e.find,"alpha");cursor=0;assert(ve_find(&e,text,&cursor)&&e.end-e.anchor==5);strcpy(e.replacement,"gamma");assert(ve_replace_all(&e,text,&cursor,sizeof(text),2000000)==1&&!strcmp(text,"A beta gamma"));assert(ve_history(&e,text,&cursor,false)&&!strcmp(text,"A beta alpha"));strcpy(text,"a\xc3\xa9z");cursor=3;e.anchor=e.end=cursor;assert(ve_delete(&e,text,&cursor,sizeof(text),false,3000000)&&!strcmp(text,"az"));for(int i=0;i<30;i++)assert(ve_insert(&e,text,&cursor,sizeof(text),"q",4000000+i*1000000,true));assert(e.un==VE_HISTORY);ve_free(&e);assert(!e.un&&!e.rn);strcpy(text,"abc");cursor=0;e.anchor=0;e.end=3;char huge[257];memset(huge,'x',256);huge[256]=0;assert(!ve_insert(&e,text,&cursor,sizeof(text),huge,0,true)&&!strcmp(text,"abc"));strcpy(e.find,"a");strcpy(e.replacement,"abcdefghijkl");assert(ve_replace_all(&e,text,&cursor,5,0)==-1&&!strcmp(text,"abc"));puts("Editor selection, undo/redo limits, UTF-8 deletion, find, replace and overflow preservation passed.");}
